        assertEquals("a&lt;b", escapeHtml("a<b"))
    }

    @Test
    fun q92_ampersand() {
        assertEquals("5 &amp; 6", escapeHtml("5 & 6"))
    }

    @Test
    fun q92_doubleQuoteAndApostrophe() {
        assertEquals("&quot;x&quot; &#39;y&#39;", escapeHtml("\"x\" 'y'"))
    }

